# <<< SPEC

# >>> HINTS
# %%brew
# Subcommands come from the COMMANDS section of man brew (ESSENTIAL COMMANDS
# first, then the rest of that section), not from `brew --help`, which only
# shows examples. Take every user-facing command there with its usage line and
# skip alias-only forms; DEVELOPER COMMANDS are out of scope.
# <<< HINTS

# >>> STATIC
_static_vulns_fix_type() {
    cat <<-'ARGCEOF'
	released	official version release
	patch	unreleased commit SHA
	any	either
	none	neither
	unreleased	no released version fix
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_alias() {
    brew alias 2>/dev/null | sed -n 's/^\([^:]*\):.*/\1/p'
}

_choice_brew_command() {
    brew commands --quiet 2>/dev/null | grep -v '^-'
}

_choice_bundle_entry() {
    local file="${argc_file:-}"
    if [[ -z "$file" ]]; then
        file="$(_argc_util_path_search_parent Brewfile)"
    fi
    [[ -n "$file" && -f "$file" ]] || return 0
    sed -n 's/^[[:space:]]*[[:alnum:]_]*[[:space:]][[:space:]]*"\([^"]*\)".*/\1/p' "$file"
}

_choice_cask() {
    brew casks 2>/dev/null
}

_choice_command() {
    _argc_util_comp_command
}

_choice_command_args() {
    _argc_util_comp_subcommand 0
}

_choice_diagnostic_check() {
    brew doctor --list-checks 2>/dev/null
}

_choice_formula() {
    brew formulae 2>/dev/null
}

_choice_installed_cask() {
    brew list --cask 2>/dev/null
}

_choice_installed_formula() {
    brew list --formula 2>/dev/null
}

_choice_installed_package() {
    _argc_util_parallel _choice_installed_formula ::: _choice_installed_cask
}

_choice_package() {
    _argc_util_parallel _choice_formula ::: _choice_cask
}

_choice_service() {
    brew services list 2>/dev/null | gawk 'NR > 1 { print $1 }'
}

_choice_tap() {
    brew tap 2>/dev/null
}

_choice_trust_target() {
    if [[ -n "${argc_taps:-}" ]]; then
        _choice_tap
    elif [[ -n "${argc_formulae:-}" ]]; then
        _choice_formula
    elif [[ -n "${argc_casks:-}" ]]; then
        _choice_cask
    elif [[ -n "${argc_commands:-}" ]]; then
        _choice_brew_command
    fi
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
